# logstash.conf — Logstash pipeline configuration
input {
  beats {
    port => 5044
    ssl => true
    ssl_certificate => "/etc/logstash/certs/logstash.crt"
    ssl_key => "/etc/logstash/certs/logstash.key"
  }
}

filter {
  # Parse Python API logs
  if [service] == "python-api" {
    grok {
      match => {
        "message" => "%{TIMESTAMP_ISO8601:timestamp} %{LOGLEVEL:level} %{DATA:logger} %{DATA:module}:%{NUMBER:line} %{GREEDYDATA:log_message}"
      }
    }

    # Parse JSON embedded in log message
    if [log_message] =~ /^\{/ {
      json {
        source => "log_message"
        target => "parsed"
      }
    }

    date {
      match => ["timestamp", "ISO8601"]
      target => "@timestamp"
    }
  }

  # Parse Java Spring Boot logs
  if [service] == "java-backend" {
    grok {
      match => {
        "message" => "%{TIMESTAMP_ISO8601:timestamp} %{LOGLEVEL:level} %{NUMBER:pid} --- \[%{DATA:thread}\] %{DATA:logger} :%{SPACE}%{GREEDYDATA:log_message}"
      }
    }

    # Extract trace IDs for distributed tracing
    if [log_message] =~ /traceId=%{UUID:trace_id}/ {
      grok {
        match => {
          "log_message" => "traceId=%{UUID:trace_id} spanId=%{UUID:span_id}"
        }
      }
    }

    date {
      match => ["timestamp", "ISO8601"]
      target => "@timestamp"
    }
  }

  # Parse Nginx access logs
  if [service] == "nginx" and [log_type] == "access" {
    grok {
      match => {
        "message" => '%{IPORHOST:client_ip} - %{DATA:remote_user} \[%{HTTPDATE:timestamp}\] "%{WORD:method} %{DATA:path} HTTP/%{NUMBER:http_version}" %{NUMBER:status_code} %{NUMBER:bytes} "%{DATA:referrer}" "%{DATA:user_agent}" %{NUMBER:request_time} %{DATA:upstream_response_time}'
      }
    }

    # GeoIP enrichment
    geoip {
      source => "client_ip"
      target => "geoip"
      database => "/usr/share/GeoIP/GeoLite2-City.mmdb"
    }

    # User agent parsing
    useragent {
      source => "user_agent"
      target => "user_agent_parsed"
    }

    mutate {
      convert => {
        "status_code" => "integer"
        "bytes" => "integer"
        "request_time" => "float"
      }
    }

    date {
      match => ["timestamp", "dd/MMM/yyyy:HH:mm:ss Z"]
      target => "@timestamp"
    }
  }

  # Add common fields
  mutate {
    add_field => {
      "[ecs][version]" => "8.11.0"
      "[host][name]" => "%{[host][hostname]}"
    }
