import boto3
from botocore.exceptions import ClientError
import json

class S3Manager:
    def __init__(self):
        self.s3 = boto3.client('s3')
        self.s3_resource = boto3.resource('s3')

    def create_secure_bucket(self, bucket_name, region='us-east-1'):
        """Create an S3 bucket with security best practices."""
        try:
            if region == 'us-east-1':
                self.s3.create_bucket(Bucket=bucket_name)
            else:
                self.s3.create_bucket(
                    Bucket=bucket_name,
                    CreateBucketConfiguration={'LocationConstraint': region}
                )

            # Block all public access
            self.s3.put_public_access_block(
                Bucket=bucket_name,
                PublicAccessBlockConfiguration={
                    'BlockPublicAcls': True,
                    'IgnorePublicAcls': True,
                    'BlockPublicPolicy': True,
                    'RestrictPublicBuckets': True
                }
            )

            # Enable encryption
            self.s3.put_bucket_encryption(
                Bucket=bucket_name,
                ServerSideEncryptionConfiguration={
                    'Rules': [{
                        'ApplyServerSideEncryptionByDefault': {
                            'SSEAlgorithm': 'AES256'
                        },
                        'BucketKeyEnabled': True
                    }]
                }
            )

            # Enable versioning
            self.s3.put_bucket_versioning(
                Bucket=bucket_name,
                VersioningConfiguration={'Status': 'Enabled'}
            )

            # Enable access logging
            self.s3.put_bucket_logging(
                Bucket=bucket_name,
                BucketLoggingStatus={
                    'LoggingEnabled': {
                        'TargetBucket': 'mycompany-logs',
                        'TargetPrefix': f'{bucket_name}/'
                    }
                }
            )

            # Lifecycle policy: transition to cheaper storage
            self.s3.put_bucket_lifecycle_configuration(
                Bucket=bucket_name,
                LifecycleConfiguration={
                    'Rules': [{
                        'ID': 'archive-old-objects',
                        'Status': 'Enabled',
                        'Filter': {'Prefix': ''},
                        'Transitions': [
                            {'Days': 30, 'StorageClass': 'STANDARD_IA'},
                            {'Days': 90, 'StorageClass': 'GLACIER'},
                            {'Days': 365, 'StorageClass': 'DEEP_ARCHIVE'}
                        ],
                        'NoncurrentVersionTransitions': [
                            {'NoncurrentDays': 30, 'StorageClass': 'STANDARD_IA'},
                            {'NoncurrentDays': 90, 'StorageClass': 'GLACIER'}
                        ],
                        'Expiration': {'Days': 2555}  # 7 years
                    }]
                }
            )

            print(f"✅ Created secure bucket: {bucket_name}")
            return True

        except ClientError as e:
            if e.response['Error']['Code'] == 'BucketAlreadyExists':
                print(f"⚠️  Bucket {bucket_name} already exists")
                return False
            raise

    def upload_with_metadata(self, bucket, key, file_path, metadata=None):
        """Upload a file with custom metadata and checksum."""
        extra_args = {
            'Metadata': metadata or {},
            'ServerSideEncryption': 'AES256',
            'StorageClass': 'STANDARD'
        }

        self.s3.upload_file(file_path, bucket, key, ExtraArgs=extra_args)
        print(f"✅ Uploaded s3://{bucket}/{key}")

    def generate_presigned_url(self, bucket, key, expiration=3600):
        """Generate a temporary download URL."""
        url = self.s3.generate_presigned_url(
            'get_object',
            Params={'Bucket': bucket, 'Key': key},
            ExpiresIn=expiration
        )
        return url

    def sync_directory(self, local_dir, bucket, prefix=''):
        """Sync a local directory to S3 (like aws s3 sync)."""
        import os
        import glob

        for file_path in glob.glob(f"{local_dir}/**/*", recursive=True):
            if os.path.isfile(file_path):
                relative_path = os.path.relpath(file_path, local_dir)
                s3_key = f"{prefix}/{relative_path}" if prefix else relative_path
                self.upload_with_metadata(bucket, s3_key, file_path)

# Lambda function for S3 event processing
LAMBDA_CODE = '''
import json
import boto3

def handler(event, context):
    s3 = boto3.client('s3')
    rekognition = boto3.client('rekognition')

    for record in event['Records']:
        bucket = record['s3']['bucket']['name']
        key = record['s3']['object']['key']

        # Example: Scan uploaded images for content moderation
        if key.endswith(('.jpg', '.jpeg', '.png')):
            response = rekognition.detect_moderation_labels(
                Image={'S3Object': {'Bucket': bucket, 'Name': key}}
            )

            if response['ModerationLabels']:
                print(f"⚠️  Moderation labels found in {key}: {response['ModerationLabels']}")
                # Move to quarantine bucket
                s3.copy_object(
                    CopySource={'Bucket': bucket, 'Key': key},
                    Bucket='quarantine-bucket',
                    Key=key
                )
                s3.delete_object(Bucket=bucket, Key=key)
            else:
                print(f"✅ Image {key} passed moderation")

    return {'statusCode': 200, 'body': json.dumps('Processing complete')}
'''

