package com.mycompany.azure.auth;

import com.azure.identity.*;
import com.azure.core.credential.TokenCredential;

public class AzureAuth {

    /**
     * Get the best available credential for the environment.
     * Production: Managed Identity or Service Principal
     * Development: Azure CLI or VS Code
     */
    public static TokenCredential getCredential() {
        return new DefaultAzureCredentialBuilder()
            // Exclude methods not available in your environment
            .excludeAzureCliCredential(false)
            .excludeAzurePowerShellCredential(true)
            .excludeEnvironmentCredential(false)
            .excludeManagedIdentityCredential(false)
            .excludeSharedTokenCacheCredential(true)
            .excludeVisualStudioCodeCredential(false)
            .build();
    }

    /**
     * Service Principal with client secret (for CI/CD pipelines)
     */
    public static TokenCredential getServicePrincipalCredential() {
        String clientId = System.getenv("AZURE_CLIENT_ID");
        String clientSecret = System.getenv("AZURE_CLIENT_SECRET");
        String tenantId = System.getenv("AZURE_TENANT_ID");

        return new ClientSecretCredentialBuilder()
            .clientId(clientId)
            .clientSecret(clientSecret)
            .tenantId(tenantId)
            .build();
    }

    /**
     * Service Principal with certificate (more secure than secret)
     */
    public static TokenCredential getCertificateCredential() {
        String clientId = System.getenv("AZURE_CLIENT_ID");
        String tenantId = System.getenv("AZURE_TENANT_ID");
        String certPath = System.getenv("AZURE_CERTIFICATE_PATH");
        String certPassword = System.getenv("AZURE_CERTIFICATE_PASSWORD");

        return new ClientCertificateCredentialBuilder()
            .clientId(clientId)
            .tenantId(tenantId)
            .pemCertificate(certPath, certPassword)
            .build();
    }

    /**
     * Managed Identity (for Azure-hosted services: VM, App Service, AKS)
     */
    public static TokenCredential getManagedIdentityCredential() {
        // System-assigned managed identity
        return new ManagedIdentityCredentialBuilder()
            .build();

        // User-assigned managed identity (specify client ID)
        // return new ManagedIdentityCredentialBuilder()
        //     .clientId("your-user-assigned-client-id")
        //     .build();
    }

    /**
     * Interactive login for local development
     */
    public static TokenCredential getInteractiveCredential() {
        return new InteractiveBrowserCredentialBuilder()
            .redirectUrl("http://localhost:8765")
            .build();
    }
}

package com.mycompany.azure;

import com.azure.core.management.AzureEnvironment;
import com.azure.core.management.Region;
import com.azure.core.management.profile.AzureProfile;
import com.azure.identity.DefaultAzureCredentialBuilder;
import com.azure.resourcemanager.AzureResourceManager;
import com.azure.resourcemanager.compute.models.*;
import com.azure.resourcemanager.network.models.*;
import com.azure.resourcemanager.resources.models.ResourceGroup;
import com.azure.resourcemanager.resources.models.DeploymentMode;
import com.azure.resourcemanager.appservice.models.*;
import java.util.Map;

public class AzureInfrastructureManager {

    private final AzureResourceManager azure;
    private final String subscriptionId;
    private final String resourceGroupName;

    public AzureInfrastructureManager(String subscriptionId, String resourceGroupName) {
        this.subscriptionId = subscriptionId;
        this.resourceGroupName = resourceGroupName;

        // Authenticate using DefaultAzureCredential
        // Checks: env vars → managed identity → Azure CLI → VS Code → etc.
        var credential = new DefaultAzureCredentialBuilder().build();
        var profile = new AzureProfile(AzureEnvironment.AZURE);

        this.azure = AzureResourceManager.configure()
            .withLogLevel(com.azure.core.management.exception.ManagementException.class)
            .authenticate(credential, profile)
            .withSubscription(subscriptionId);
    }

    /**
     * Create a Resource Group with tags
     */
    public ResourceGroup createResourceGroup(String region) {
        System.out.println("🔨 Creating Resource Group: " + resourceGroupName);

        return azure.resourceGroups().define(resourceGroupName)
            .withRegion(Region.fromName(region))
            .withTag("Project", "devops-app")
            .withTag("Environment", "production")
            .withTag("ManagedBy", "java-sdk")
            .withTag("CostCenter", "engineering")
            .create();
    }

    /**
     * Create a Virtual Machine for Java backend
     */
    public VirtualMachine createVirtualMachine(
            String vmName, String subnetName, String adminUser) {

        System.out.println("🖥️  Creating VM: " + vmName);

        // Create virtual network
        Network network = azure.networks().define(resourceGroupName + "-vnet")
            .withRegion(Region.US_EAST)
            .withExistingResourceGroup(resourceGroupName)
            .withAddressSpace("10.0.0.0/16")
            .withSubnet(subnetName, "10.0.1.0/24")
            .create();

        // Create public IP address
        PublicIpAddress publicIp = azure.publicIpAddresses().define(vmName + "-ip")
            .withRegion(Region.US_EAST)
            .withExistingResourceGroup(resourceGroupName)
            .withDynamicIP()
            .withSku(PublicIPSkuType.STANDARD)
            .withTag("Name", vmName + "-ip")
            .create();

        // Create network interface
        NetworkInterface nic = azure.networkInterfaces().define(vmName + "-nic")
            .withRegion(Region.US_EAST)
            .withExistingResourceGroup(resourceGroupName)
            .withExistingPrimaryNetwork(network)
            .withSubnet(subnetName)
            .withPrimaryPrivateIPAddressDynamic()
            .withExistingPrimaryPublicIPAddress(publicIp)
            .withAcceleratedNetworking(true)
            .create();

        // Cloud-init script for bootstrapping
        String cloudInit = String.format("""
            #cloud-config
            package_update: true
            packages:
              - docker.io
              - openjdk-17-jdk
              - nginx
              - htop
              - jq
            runcmd:
              - systemctl start docker
              - systemctl enable docker
              - usermod -aG docker %s
              - echo 'vm.max_map_count=262144' >> /etc/sysctl.conf
              - sysctl -p
            """, adminUser);

        // Create VM with cloud-init
        VirtualMachine vm = azure.virtualMachines().define(vmName)
            .withRegion(Region.US_EAST)
            .withExistingResourceGroup(resourceGroupName)
            .withExistingPrimaryNetworkInterface(nic)
            .withPopularLinuxImage(KnownLinuxVirtualMachineImage.UBUNTU_SERVER_22_04_LTS)
            .withRootUsername(adminUser)
            .withSsh(sshPublicKey())
            .withSize(VirtualMachineSizeTypes.STANDARD_B2S)
            .withOSDiskCaching(CachingTypes.READ_WRITE)
            .withOSDiskName(vmName + "-osdisk")
            .withOSDiskSizeInGB(30)
            .withOSDiskStorageAccountType(StorageAccountTypes.STANDARD_SSD_LRS)
            .withCustomData(cloudInit)
            .withBootDiagnostics()
            .withTags(Map.of(
                "Name", vmName,
                "Project", "devops-app",
                "Role", "application-server",
                "Environment", "production"
            ))
            .create();

        System.out.println("✅ VM created: " + vm.id());
        System.out.println("   Public IP: " + publicIp.ipAddress());
        System.out.println("   Private IP: " + nic.primaryPrivateIP());
        return vm;
    }

    /**
     * Create Azure App Service for Python API (Platform-as-a-Service)
     */
    public WebApp createAppService(String appName, String dockerImage) {
        System.out.println("🌐 Creating App Service: " + appName);

        // Create App Service Plan (the "server" that runs your app)
        AppServicePlan plan = azure.appServicePlans().define(resourceGroupName + "-plan")
            .withRegion(Region.US_EAST)
            .withExistingResourceGroup(resourceGroupName)
            .withPricingTier(PricingTier.PREMIUM_P1V3)
            .withOperatingSystem(OperatingSystem.LINUX)
            .withCapacity(2)  // 2 instances for HA
            .withPerSiteScaling(false)
            .withTags(Map.of(
                "Name", resourceGroupName + "-plan",
                "Project", "devops-app"
            ))
            .create();

        // Create Web App with Docker container
        WebApp app = azure.webApps().define(appName)
            .withExistingLinuxAppServicePlan(plan)
            .withExistingResourceGroup(resourceGroupName)
            .withPublicDockerHubImage(dockerImage)
            .withAppSetting("WEBSITES_PORT", "5000")
            .withAppSetting("WEBSITES_ENABLE_APP_SERVICE_STORAGE", "false")
            .withAppSetting("PYTHON_ENV", "production")
            .withAppSetting("FLASK_ENV", "production")
            .withAppSetting("LOG_LEVEL", "info")
            .withAppSetting("WORKERS", "4")
            .withConnectionString("Database", ConnectionStringType.SQLAZURE,
                getSecretFromKeyVault("db-connection-string"))
            .withConnectionString("Redis", ConnectionStringType.CUSTOM,
                getSecretFromKeyVault("redis-connection-string"))
            .withWebAppAlwaysOn(true)
            .withHttpsOnly(true)
            .withManagedServiceIdentity()  // Enable Managed Identity
            .withWebSocketsEnabled(false)
            .withFtpsState(FtpsState.DISABLED)  // Security: disable FTP
            .withHttp20Enabled(true)
            .withMinTlsVersion(SupportedTlsVersions.ONE_DOT_TWO)
            .withScmSiteAlsoStopped(false)
            .withTags(Map.of(
                "Name", appName,
                "Project", "devops-app",
                "Environment", "production"
            ))
            .create();

        // Configure diagnostic logs
        azure.diagnosticSettings().define(appName + "-diagnostics")
            .withResource(app.id())
            .withLogAnalytics("/subscriptions/.../workspaces/myworkspace")
            .withLog("AppServiceHTTPLogs", 7)
            .withLog("AppServiceConsoleLogs", 7)
            .withMetric("AllMetrics", 7)
            .create();

        System.out.println("✅ App Service created: " + app.defaultHostName());
        System.out.println("   URL: https://" + app.defaultHostName());
        return app;
    }

    /**
     * Configure Auto-Scale for App Service Plan
     */
    public void configureAutoScale(String appServicePlanId) {
        System.out.println("📈 Configuring auto-scale...");

        azure.autoscaleSettings().define(resourceGroupName + "-autoscale")
            .withRegion(Region.US_EAST)
            .withExistingResourceGroup(resourceGroupName)
            .withTargetResource(appServicePlanId)
            .withProfile(
                azure.autoscaleSettings().defineAutoscaleProfile("default-profile")
                    .withFixedInstanceCount(2)
                    .withScaleBasedOnMetric(
                        azure.autoscaleSettings().defineScaleRule()
                            .withMetricSource(appServicePlanId)
                            .withMetricName("CpuPercentage")
                            .withStatistic(MetricStatistic.AVERAGE)
                            .withTimeWindow(java.time.Duration.ofMinutes(5))
                            .withCondition(MetricAlertRuleCondition.GREATER_THAN, 70)
                            .withScaleAction(ScaleDirection.INCREASE, ScaleType.CHANGE_COUNT, 1, java.time.Duration.ofMinutes(1))
                            .attach()
                    )
                    .withScaleBasedOnMetric(
                        azure.autoscaleSettings().defineScaleRule()
                            .withMetricSource(appServicePlanId)
                            .withMetricName("CpuPercentage")
                            .withStatistic(MetricStatistic.AVERAGE)
                            .withTimeWindow(java.time.Duration.ofMinutes(10))
                            .withCondition(MetricAlertRuleCondition.LESS_THAN, 30)
                            .withScaleAction(ScaleDirection.DECREASE, ScaleType.CHANGE_COUNT, 1, java.time.Duration.ofMinutes(5))
                            .attach()
                    )
                    .withMinInstanceCount(2)
                    .withMaxInstanceCount(10)
                    .attach()
            )
            .create();

        System.out.println("✅ Auto-scale configured");
    }

    /**
     * Create Azure Load Balancer for VM scale set
     */
    public LoadBalancer createLoadBalancer(String lbName) {
        System.out.println("⚖️  Creating Load Balancer: " + lbName);

        // Create public IP for LB
        PublicIpAddress lbPublicIp = azure.publicIpAddresses().define(lbName + "-ip")
            .withRegion(Region.US_EAST)
            .withExistingResourceGroup(resourceGroupName)
            .withStaticIP()
            .withSku(PublicIPSkuType.STANDARD)
            .withTags(Map.of("Name", lbName + "-ip"))
            .create();

        // Create Load Balancer
        LoadBalancer lb = azure.loadBalancers().define(lbName)
            .withRegion(Region.US_EAST)
            .withExistingResourceGroup(resourceGroupName)
            .withSku(LoadBalancerSkuType.STANDARD)
            .withFrontend(lbName + "-frontend", lbPublicIp.id())
            .withBackend(lbName + "-backend")
            .withLoadBalancingRule(
                lbName + "-http-rule",
                TransportProtocol.TCP,
                80, 80,
                lbName + "-frontend",
                lbName + "-backend"
            )
            .withLoadBalancingRule(
                lbName + "-https-rule",
                TransportProtocol.TCP,
                443, 443,
                lbName + "-frontend",
                lbName + "-backend"
            )
            .withProbe(lbName + "-health-probe", "HTTP", "/health", 80, java.time.Duration.ofSeconds(5), 2, 2)
            .withTags(Map.of("Name", lbName))
            .create();

        System.out.println("✅ Load Balancer created: " + lbPublicIp.ipAddress());
        return lb;
    }

    /**
     * Create Network Security Group with rules
     */
    public NetworkSecurityGroup createSecurityGroup(String nsgName) {
        System.out.println("🔒 Creating NSG: " + nsgName);

        return azure.networkSecurityGroups().define(nsgName)
            .withRegion(Region.US_EAST)
            .withExistingResourceGroup(resourceGroupName)
            .defineRule("Allow-SSH")
                .allowInbound()
                .fromAddress("10.0.0.0/8")
                .fromAnyPort()
                .toAnyAddress()
                .toPort(22)
                .withProtocol(SecurityRuleProtocol.TCP)
                .withPriority(100)
                .attach()
            .defineRule("Allow-HTTP")
                .allowInbound()
                .fromInternet()
                .fromAnyPort()
                .toAnyAddress()
                .toPort(80)
                .withProtocol(SecurityRuleProtocol.TCP)
                .withPriority(110)
                .attach()
            .defineRule("Allow-HTTPS")
                .allowInbound()
                .fromInternet()
                .fromAnyPort()
                .toAnyAddress()
                .toPort(443)
                .withProtocol(SecurityRuleProtocol.TCP)
                .withPriority(120)
                .attach()
            .defineRule("Deny-All-Inbound")
                .denyInbound()
                .fromAnyAddress()
                .fromAnyPort()
                .toAnyAddress()
                .toAnyPort()
                .withAnyProtocol()
                .withPriority(4096)
                .attach()
            .withTags(Map.of("Name", nsgName))
            .create();
    }

    // Key Vault integration for secrets
    private String getSecretFromKeyVault(String secretName) {
        com.azure.security.keyvault.secrets.SecretClient secretClient = 
            new com.azure.security.keyvault.secrets.SecretClientBuilder()
                .vaultUrl("https://mycompany-keyvault.vault.azure.net/")
                .credential(new DefaultAzureCredentialBuilder().build())
                .buildClient();

        return secretClient.getSecret(secretName).getValue();
    }

    private String sshPublicKey() {
        return System.getenv("AZURE_VM_SSH_KEY");
    }

    /**
     * Clean up all resources
     */
    public void cleanup() {
        System.out.println("🗑️  Deleting Resource Group: " + resourceGroupName);
        azure.resourceGroups().beginDeleteByName(resourceGroupName);
        System.out.println("✅ Resource group deletion initiated");
    }

    public static void main(String[] args) {
        var manager = new AzureInfrastructureManager(
            "12345678-1234-1234-1234-123456789012",
            "devops-app-production"
        );

        // Create infrastructure
        manager.createResourceGroup("eastus");
        manager.createVirtualMachine("java-backend-01", "subnet-1", "azureuser");
        manager.createAppService("python-api-prod", "myregistry/python-api:2.1.0");
        manager.createLoadBalancer("app-lb");
        manager.createSecurityGroup("app-nsg");
    }
}

