            .buildClient();
    }

    /**
     * Create a secure container with private access
     */
    public BlobContainerClient createSecureContainer(String containerName) {
        BlobContainerClient container = blobServiceClient.getBlobContainerClient(containerName);

        if (!container.exists()) {
            container.create();

            // Set public access to none (private only)
            container.setAccessPolicy(PublicAccessType.NONE, null);

            System.out.println("✅ Created container: " + containerName);
        }

        return container;
    }

    /**
     * Upload a blob with metadata and tier
     */
    public void uploadBlob(String containerName, String blobName, 
                          InputStream data, long length) {
        BlobClient blobClient = blobServiceClient
            .getBlobContainerClient(containerName)
            .getBlobClient(blobName);

        // Upload with metadata and access tier
        BlobParallelUploadOptions options = new BlobParallelUploadOptions(data, length)
            .setMetadata(Map.of(
                "uploadedBy", "java-backend",
                "uploadTime", OffsetDateTime.now().toString(),
                "contentType", "application/octet-stream",
                "project", "devops-app"
            ))
            .setTier(AccessTier.HOT);  // Hot tier for frequently accessed data

        blobClient.uploadWithResponse(options, null, null);
        System.out.println("✅ Uploaded: " + blobName);
    }

    /**
     * Upload from file with content type detection
     */
    public void uploadFromFile(String containerName, String blobName, String filePath) {
        BlobClient blobClient = blobServiceClient
            .getBlobContainerClient(containerName)
            .getBlobClient(blobName);

        blobClient.uploadFromFile(filePath, true);  // true = overwrite

        // Set HTTP headers based on file extension
        String contentType = detectContentType(filePath);
        blobClient.setHttpHeaders(new BlobHttpHeaders()
            .setContentType(contentType)
            .setContentEncoding("gzip")
        );

        System.out.println("✅ Uploaded from file: " + blobName + " (" + contentType + ")");
    }

    /**
     * Generate a time-limited SAS URL for secure sharing
     */
    public String generateSasUrl(String containerName, String blobName, Duration expiry) {
        BlobClient blobClient = blobServiceClient
            .getBlobContainerClient(containerName)
            .getBlobClient(blobName);

        BlobSasPermission permission = new BlobSasPermission()
            .setReadPermission(true);

        OffsetDateTime expiration = OffsetDateTime.now().plus(expiry);

        BlobServiceSasSignatureValues sasValues = new BlobServiceSasSignatureValues(expiration, permission)
            .setStartTime(OffsetDateTime.now())
            .setProtocol(SasProtocol.HTTPS_ONLY);  // Force HTTPS

        String sasToken = blobClient.generateSas(sasValues);
        return blobClient.getBlobUrl() + "?" + sasToken;
    }

    /**
     * List all blobs in a container with properties
     */
    public void listBlobs(String containerName) {
        BlobContainerClient container = blobServiceClient.getBlobContainerClient(containerName);

        container.listBlobs().forEach(blobItem -> {
            System.out.printf("  %-40s | %s | %8d bytes | %s%n",
                blobItem.getName(),
                blobItem.getProperties().getCreationTime(),
                blobItem.getProperties().getContentLength(),
                blobItem.getProperties().getAccessTier()
            );
        });
    }

    /**
     * Archive old blobs to save costs (lifecycle management)
     */
    public void archiveOldBlobs(String containerName, int daysOld) {
        BlobContainerClient container = blobServiceClient.getBlobContainerClient(containerName);
        OffsetDateTime cutoff = OffsetDateTime.now().minusDays(daysOld);

        container.listBlobs().forEach(blobItem -> {
            if (blobItem.getProperties().getCreationTime().isBefore(cutoff)) {
                BlobClient blobClient = container.getBlobClient(blobItem.getName());
                blobClient.setAccessTier(AccessTier.ARCHIVE);
                System.out.println("📦 Archived: " + blobItem.getName());
            }
        });
    }

    /**
     * Delete a blob
     */
    public void deleteBlob(String containerName, String blobName) {
        BlobClient blobClient = blobServiceClient
            .getBlobContainerClient(containerName)
            .getBlobClient(blobName);

        blobClient.delete();
        System.out.println("🗑️  Deleted: " + blobName);
    }

    /**
     * Download blob to file
     */
    public void downloadBlob(String containerName, String blobName, String destinationPath) {
        BlobClient blobClient = blobServiceClient
            .getBlobContainerClient(containerName)
            .getBlobClient(blobName);

        blobClient.downloadToFile(destinationPath, true);
        System.out.println("📥 Downloaded: " + blobName + " → " + destinationPath);
    }

    /**
     * Copy blob between containers (cross-region support)
     */
    public void copyBlob(String sourceContainer, String sourceBlob,
                         String destContainer, String destBlob) {
        BlobClient sourceClient = blobServiceClient
            .getBlobContainerClient(sourceContainer)
            .getBlobClient(sourceBlob);

        BlobClient destClient = blobServiceClient
            .getBlobContainerClient(destContainer)
            .getBlobClient(destBlob);

        String sourceUrl = sourceClient.getBlobUrl();
        destClient.copyFromUrl(sourceUrl);
        System.out.println("📋 Copied: " + sourceBlob + " → " + destBlob);
    }

    private String detectContentType(String filePath) {
        if (filePath.endsWith(".json")) return "application/json";
        if (filePath.endsWith(".xml")) return "application/xml";
        if (filePath.endsWith(".csv")) return "text/csv";
        if (filePath.endsWith(".pdf")) return "application/pdf";
        if (filePath.endsWith(".jpg") || filePath.endsWith(".jpeg")) return "image/jpeg";
        if (filePath.endsWith(".png")) return "image/png";
        if (filePath.endsWith(".tar.gz")) return "application/gzip";
        return "application/octet-stream";
    }

    public static void main(String[] args) throws Exception {
        var manager = new AzureBlobManager(System.getenv("AZURE_STORAGE_CONNECTION_STRING"));

        manager.createSecureContainer("app-backups");
        manager.uploadFromFile("app-backups", "backup-2026-08-10.tar.gz", "/tmp/backup.tar.gz");

        String downloadUrl = manager.generateSasUrl(
            "app-backups", "backup-2026-08-10.tar.gz", Duration.ofHours(1));
        System.out.println("📥 Download URL (1 hour): " + downloadUrl);

        manager.listBlobs("app-backups");
        manager.archiveOldBlobs("app-backups", 90);
    }
}

package com.mycompany.azure.arm;

