import com.azure.resourcemanager.resources.models.DeploymentProperties;
import com.azure.resourcemanager.resources.models.TemplateLink;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import java.util.Map;
import java.util.List;

public class ArmTemplateDeployer {

    private final com.azure.resourcemanager.AzureResourceManager azure;
    private final ObjectMapper mapper;

    public ArmTemplateDeployer(com.azure.resourcemanager.AzureResourceManager azure) {
        this.azure = azure;
        this.mapper = new ObjectMapper()
            .enable(SerializationFeature.INDENT_OUTPUT);
    }

    /**
     * Deploy infrastructure from an ARM template
     */
    public void deployFromTemplate(String deploymentName, String resourceGroup, 
                                   Map<String, Object> template, Map<String, Object> parameters) {

        String templateJson;
        try {
            templateJson = mapper.writeValueAsString(template);
        } catch (Exception e) {
            throw new RuntimeException("Failed to serialize template", e);
        }

        // Deploy with incremental mode (only add/change, don't delete)
        azure.deployments().define(deploymentName)
            .withExistingResourceGroup(resourceGroup)
            .withTemplate(templateJson)
            .withParameters(parameters)
            .withMode(DeploymentMode.INCREMENTAL)
            .create();

        System.out.println("⏳ Deploying ARM template: " + deploymentName);

        // Poll for completion
        var deployment = azure.deployments()
            .getByResourceGroup(resourceGroup, deploymentName);

        while (!deployment.provisioningState().equals("Succeeded")) {
            if (deployment.provisioningState().equals("Failed")) {
                throw new RuntimeException("Deployment failed: " + deploymentName);
            }
            try {
                Thread.sleep(10000);  // Wait 10 seconds
                deployment.refresh();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException("Deployment interrupted", e);
            }
        }

        System.out.println("✅ ARM deployment complete: " + deploymentName);
    }

    /**
     * Deploy from a remote template URL (e.g., from Azure Quickstart Templates)
     */
    public void deployFromUrl(String deploymentName, String resourceGroup,
                              String templateUrl, Map<String, Object> parameters) {

        azure.deployments().define(deploymentName)
            .withExistingResourceGroup(resourceGroup)
            .withTemplateLink(templateUrl, "1.0.0.0")
            .withParameters(parameters)
            .withMode(DeploymentMode.INCREMENTAL)
            .create();

        System.out.println("✅ Deployed from URL: " + templateUrl);
    }

