package com.mycompany.azure.monitoring;

import com.azure.monitor.query.LogsQueryClient;
import com.azure.monitor.query.LogsQueryClientBuilder;
import com.azure.monitor.query.models.LogsBatchQuery;
import com.azure.monitor.query.models.LogsQueryResult;
import com.azure.identity.DefaultAzureCredentialBuilder;

import java.time.Duration;

public class AzureMonitorManager {

    private final LogsQueryClient logsClient;
    private final String workspaceId;

    public AzureMonitorManager(String workspaceId) {
        this.workspaceId = workspaceId;
        this.logsClient = new LogsQueryClientBuilder()
            .credential(new DefaultAzureCredentialBuilder().build())
            .buildClient();
    }

    /**
     * Query application logs with Kusto Query Language (KQL)
     */
    public void queryAppLogs(String appName, Duration timeRange) {
        String query = String.format("""
            AppServiceConsoleLogs
            | where TimeGenerated > ago(%dm)
            | where _ResourceId contains '%s'
            | where ResultDescription contains 'ERROR' or ResultDescription contains 'Exception'
            | project TimeGenerated, Level, ResultDescription
            | order by TimeGenerated desc
            | take 50
            """, timeRange.toMinutes(), appName);

        LogsQueryResult result = logsClient.queryWorkspace(workspaceId, query, null);

        System.out.println("🔍 Recent errors in " + appName + ":");
        for (var row : result.getTable().getRows()) {
            System.out.printf("  [%s] %s: %s%n",
                row.getColumnValue("TimeGenerated"),
                row.getColumnValue("Level"),
                row.getColumnValue("ResultDescription")
            );
        }
    }

    /**
     * Query VM CPU metrics
     */
    public void queryVmMetrics(String vmName) {
        String query = String.format("""
            Perf
            | where TimeGenerated > ago(1h)
            | where ObjectName == 'Processor' and CounterName == '% Processor Time'
            | where _ResourceId contains '%s'
            | summarize AvgCPU = avg(CounterValue), MaxCPU = max(CounterValue) by bin(TimeGenerated, 5m)
            | order by TimeGenerated desc
            """, vmName);

        LogsQueryResult result = logsClient.queryWorkspace(workspaceId, query, null);

        System.out.println("📊 CPU usage for " + vmName + ":");
        for (var row : result.getTable().getRows()) {
            System.out.printf("  %s | Avg: %.1f%% | Max: %.1f%%%n",
                row.getColumnValue("TimeGenerated"),
                Double.parseDouble(row.getColumnValue("AvgCPU")),
                Double.parseDouble(row.getColumnValue("MaxCPU"))
            );
        }
    }

    /**
     * Batch query multiple metrics at once
     */
    public void batchQuery() {
        LogsBatchQuery batchQuery = new LogsBatchQuery();

        String queryId1 = batchQuery.addWorkspaceQuery(workspaceId,
            "AppRequests | summarize count() by bin(TimeGenerated, 1h)",
            null, Duration.ofHours(1));

        String queryId2 = batchQuery.addWorkspaceQuery(workspaceId,
            "AppExceptions | summarize count() by bin(TimeGenerated, 1h)",
            null, Duration.ofHours(1));

        var batchResult = logsClient.queryBatch(batchQuery);

        System.out.println("📈 Requests per hour:");
        for (var row : batchResult.getResult(queryId1).getTable().getRows()) {
            System.out.println("  " + row.getColumnValue("TimeGenerated") + ": " + row.getColumnValue("count_"));
        }

        System.out.println("🐛 Exceptions per hour:");
        for (var row : batchResult.getResult(queryId2).getTable().getRows()) {
            System.out.println("  " + row.getColumnValue("TimeGenerated") + ": " + row.getColumnValue("count_"));
        }
    }

    /**
     * Create alert rule for high CPU
     */
    public void createCpuAlert(String vmId, String actionGroupId) {
        com.azure.resourcemanager.monitor.MonitorManager monitorManager = 
            com.azure.resourcemanager.monitor.MonitorManager.authenticate(
                new DefaultAzureCredentialBuilder().build(),
                new com.azure.core.management.profile.AzureProfile(com.azure.core.management.AzureEnvironment.AZURE)
            );

        monitorManager.alertRules().define("high-cpu-alert")
            .withExistingResourceGroup("devops-app-production")
            .withTargetResource(vmId)
            .withCondition(
                "Percentage CPU",
                com.azure.resourcemanager.monitor.models.AggregationType.AVERAGE,
                com.azure.resourcemanager.monitor.models.ConditionOperator.GREATER_THAN,
                80.0
            )
            .withPeriod(java.time.Duration.ofMinutes(5))
            .withEvaluationFrequency(java.time.Duration.ofMinutes(1))
            .withSeverity(2)  // Warning
            .withActionGroups(actionGroupId)
            .withDescription("Alert when CPU exceeds 80% for 5 minutes")
            .create();

        System.out.println("🚨 Created high CPU alert");
    }

    public static void main(String[] args) {
        var monitor = new AzureMonitorManager(
            "12345678-1234-1234-1234-123456789012"  // Log Analytics workspace ID
        );

        monitor.queryAppLogs("python-api-prod", Duration.ofMinutes(30));
        monitor.queryVmMetrics("java-backend-01");
        monitor.batchQuery();
    }
}

package com.mycompany.azure.cost;

import com.azure.resourcemanager.AzureResourceManager;
import com.azure.identity.DefaultAzureCredentialBuilder;
import com.azure.core.management.profile.AzureProfile;
import com.azure.core.management.AzureEnvironment;
import java.time.OffsetDateTime;
import java.time.format.DateTimeFormatter;
import java.util.Map;

public class AzureCostManager {

    private final AzureResourceManager azure;
    private final String subscriptionId;

    public AzureCostManager(String subscriptionId) {
        this.subscriptionId = subscriptionId;
        var credential = new DefaultAzureCredentialBuilder().build();
        var profile = new AzureProfile(AzureEnvironment.AZURE);
        this.azure = AzureResourceManager.authenticate(credential, profile)
            .withSubscription(subscriptionId);
    }

    /**
     * Get cost analysis by resource group
     */
    public void analyzeCostsByResourceGroup() {
        System.out.println("💰 Cost Analysis by Resource Group:");
        System.out.println("=====================================");

        for (var rg : azure.resourceGroups().list()) {
            // In real implementation, use Azure Cost Management REST API
            // This is a simplified representation
            System.out.printf("  %-30s | $%.2f/month%n", 
                rg.name(), 
                estimateMonthlyCost(rg.name())
            );
        }
    }

    /**
     * Estimate monthly cost based on resource types
     */
    private double estimateMonthlyCost(String resourceGroupName) {
        double total = 0.0;

        var resources = azure.genericResources().listByResourceGroup(resourceGroupName);
        for (var resource : resources) {
            total += getResourceCostEstimate(resource.resourceType());
        }

        return total;
    }

    private double getResourceCostEstimate(String resourceType) {
        return switch (resourceType) {
            case "Microsoft.Compute/virtualMachines" -> 45.50;
            case "Microsoft.Web/serverFarms" -> 73.00;
            case "Microsoft.Sql/servers" -> 150.00;
            case "Microsoft.Storage/storageAccounts" -> 25.00;
            case "Microsoft.Network/loadBalancers" -> 18.00;
            case "Microsoft.Network/publicIPAddresses" -> 3.60;
            default -> 10.00;
        };
    }

    /**
     * Apply tags for cost tracking
     */
    public void tagResourcesForCostTracking(String resourceGroupName) {
        var resources = azure.genericResources().listByResourceGroup(resourceGroupName);

        for (var resource : resources) {
            resource.update()
                .withTag("CostCenter", "engineering")
                .withTag("Environment", "production")
                .withTag("Project", "devops-app")
                .withTag("Owner", "platform-team@mycompany.com")
                .withTag("BudgetAlert", "1000")
                .apply();

            System.out.println("🏷️  Tagged: " + resource.name());
        }
    }

    /**
     * Find unused resources to decommission
     */
    public void findUnusedResources() {
        System.out.println("🔍 Scanning for unused resources...");

        // Check for VMs with low CPU utilization
        for (var vm : azure.virtualMachines().list()) {
            // In production, query Azure Monitor metrics
            // This is a simplified check
            if (vm.tags().containsKey("AutoShutdown") && 
                vm.tags().get("AutoShutdown").equals("true")) {
                System.out.println("  ⚠️  VM marked for auto-shutdown: " + vm.name());
            }
        }

        // Check for unattached disks
        for (var disk : azure.disks().list()) {
            if (disk.isAttachedToVirtualMachine()) {
                System.out.println("  💾 Unattached disk: " + disk.name() + " (" + disk.sizeInGB() + " GB)");
            }
        }

        // Check for old snapshots
        for (var snapshot : azure.snapshots().list()) {
            if (snapshot.creationTime().isBefore(OffsetDateTime.now().minusDays(30))) {
                System.out.println("  📸 Old snapshot: " + snapshot.name() + " (created " + snapshot.creationTime() + ")");
            }
        }
    }

    /**
     * Create budget alert
     */
    public void createBudgetAlert(String budgetName, double amount, String[] contactEmails) {
        // In production, use Azure Cost Management SDK
        System.out.println("📊 Creating budget: " + budgetName);
        System.out.println("   Amount: $" + amount);
        System.out.println("   Alerts at: 80%, 100%, 120%");
        System.out.println("   Contacts: " + String.join(", ", contactEmails));
    }

    /**
     * Generate cost optimization report
     */
    public void generateOptimizationReport() {
        System.out.println("\n📋 Cost Optimization Report");
        System.out.println("===========================");

        System.out.println("\n1. Right-sizing opportunities:");
        System.out.println("   - java-backend-01: Consider B2s → B1s (saves $15/month)");
        System.out.println("   - python-api-plan: P1v3 is appropriate for current load");

        System.out.println("\n2. Reserved Instance recommendations:");
        System.out.println("   - Commit to 1-year RI for java-backend VMs (save 30%)");
        System.out.println("   - App Service Plan: already optimized");

        System.out.println("\n3. Storage optimization:");
        System.out.println("   - Move old backups to Cool tier (save 40%)");
        System.out.println("   - Delete snapshots older than 90 days");

        System.out.println("\n4. Network optimization:");
        System.out.println("   - Consider VNet peering instead of public IPs");
        System.out.println("   - Enable CDN for static assets");
    }

    public static void main(String[] args) {
        var costManager = new AzureCostManager(
            "12345678-1234-1234-1234-123456789012"
        );

        costManager.analyzeCostsByResourceGroup();
        costManager.tagResourcesForCostTracking("devops-app-production");
        costManager.findUnusedResources();
