package com.mycompany.azure.security;

import com.azure.security.keyvault.secrets.SecretClient;
import com.azure.security.keyvault.secrets.SecretClientBuilder;
import com.azure.security.keyvault.secrets.models.KeyVaultSecret;
import com.azure.security.keyvault.keys.KeyClient;
import com.azure.security.keyvault.keys.KeyClientBuilder;
import com.azure.security.keyvault.keys.models.CreateRsaKeyOptions;
import com.azure.security.keyvault.certificates.CertificateClient;
import com.azure.security.keyvault.certificates.CertificateClientBuilder;
import com.azure.identity.DefaultAzureCredentialBuilder;
import java.time.OffsetDateTime;

public class KeyVaultManager {

    private final SecretClient secretClient;
    private final KeyClient keyClient;
    private final CertificateClient certificateClient;
    private final String vaultUrl;

    public KeyVaultManager(String vaultName) {
        this.vaultUrl = "https://" + vaultName + ".vault.azure.net/";
        var credential = new DefaultAzureCredentialBuilder().build();

        this.secretClient = new SecretClientBuilder()
            .vaultUrl(vaultUrl)
            .credential(credential)
            .buildClient();

        this.keyClient = new KeyClientBuilder()
            .vaultUrl(vaultUrl)
            .credential(credential)
            .buildClient();

        this.certificateClient = new CertificateClientBuilder()
            .vaultUrl(vaultUrl)
            .credential(credential)
            .buildClient();
    }

    /**
     * Store a secret with expiration and tags
     */
    public void storeSecret(String name, String value, int expiryDays, String description) {
        KeyVaultSecret secret = new KeyVaultSecret(name, value)
            .setProperties(new com.azure.security.keyvault.secrets.models.SecretProperties()
                .setExpiresOn(OffsetDateTime.now().plusDays(expiryDays))
                .setContentType("text/plain")
                .setTags(Map.of(
                    "description", description,
                    "environment", "production",
                    "rotation-required", "true",
                    "created-by", "java-backend"
                ))
            );

        secretClient.setSecret(secret);
        System.out.println("🔐 Stored secret: " + name + " (expires in " + expiryDays + " days)");
    }

    /**
     * Retrieve a secret (used by apps at runtime)
     */
    public String getSecret(String name) {
        KeyVaultSecret secret = secretClient.getSecret(name);
        System.out.println("🔓 Retrieved secret: " + name);
        return secret.getValue();
    }

    /**
     * Rotate a secret (create new version, invalidate old)
     */
    public void rotateSecret(String name, String newValue) {
        // Get current secret properties
        var current = secretClient.getSecret(name);

        // Store new version
        KeyVaultSecret newSecret = new KeyVaultSecret(name, newValue)
            .setProperties(new com.azure.security.keyvault.secrets.models.SecretProperties()
                .setExpiresOn(OffsetDateTime.now().plusDays(90))
                .setContentType("text/plain")
                .setTags(Map.of(
                    "description", current.getProperties().getTags().get("description"),
                    "rotated-at", OffsetDateTime.now().toString(),
                    "previous-version", current.getProperties().getVersion()
                ))
            );

        secretClient.setSecret(newSecret);
        System.out.println("🔄 Rotated secret: " + name);
    }

    /**
     * Create an RSA key for encryption
     */
    public void createEncryptionKey(String keyName) {
        CreateRsaKeyOptions options = new CreateRsaKeyOptions(keyName)
            .setKeySize(2048)
            .setExpiresOn(OffsetDateTime.now().plusYears(1))
            .setTags(Map.of("purpose", "app-encryption", "environment", "production"));

        keyClient.createRsaKey(options);
        System.out.println("🔑 Created RSA key: " + keyName);
    }

    /**
     * List all secrets with their status
     */
    public void auditSecrets() {
        System.out.println("🔍 Key Vault Audit: " + vaultUrl);
        System.out.println("================================");

        for (var secretProperties : secretClient.listPropertiesOfSecrets()) {
            var secret = secretClient.getSecret(secretProperties.getName());
            var props = secret.getProperties();

            String status = props.getExpiresOn().isBefore(OffsetDateTime.now().plusDays(7)) 
                ? "⚠️  EXPIRING SOON" : "✅ Active";

            System.out.printf("  %-30s | %s | Expires: %s | %s%n",
                secret.getName(),
                status,
                props.getExpiresOn(),
                props.getTags().getOrDefault("description", "N/A")
            );
        }
    }

    /**
     * Backup secret to secondary vault (disaster recovery)
     */
    public void backupToSecondaryVault(String secretName, String secondaryVaultName) {
        String secondaryUrl = "https://" + secondaryVaultName + ".vault.azure.net/";
        SecretClient secondaryClient = new SecretClientBuilder()
            .vaultUrl(secondaryUrl)
            .credential(new DefaultAzureCredentialBuilder().build())
            .buildClient();

        String value = getSecret(secretName);
        secondaryClient.setSecret(secretName, value);
        System.out.println("📦 Backed up " + secretName + " to " + secondaryVaultName);
    }

    public static void main(String[] args) {
        var vault = new KeyVaultManager("mycompany-keyvault");

        // Store application secrets
        vault.storeSecret("db-connection-string", 
            "jdbc:postgresql://mydb.postgres.database.azure.com:5432/appdb?user=admin&password=...", 
            90, "Production database connection");
        vault.storeSecret("redis-connection-string", 
            "redis://myredis.redis.cache.windows.net:6380?ssl=true&password=...", 
            90, "Redis cache connection");
        vault.storeSecret("api-external-key", 
            "sk-live-abc123xyz789", 
            30, "Third-party API key");

        // Retrieve at runtime
        String dbUrl = vault.getSecret("db-connection-string");

        // Audit
        vault.auditSecrets();

        // Rotate critical secrets
        vault.rotateSecret("api-external-key", "sk-live-new456def012");

        // Create encryption key
        vault.createEncryptionKey("app-data-encryption");

        // Backup to DR vault
        vault.backupToSecondaryVault("db-connection-string", "mycompany-keyvault-dr");
    }
}

package com.mycompany.azure.aks;

import com.azure.resourcemanager.AzureResourceManager;
import com.azure.resourcemanager.containerservice.models.*;
import com.azure.core.management.Region;
import com.azure.identity.DefaultAzureCredentialBuilder;
import com.azure.core.management.profile.AzureProfile;
import com.azure.core.management.AzureEnvironment;
import java.util.Map;
import java.util.List;

public class AksManager {

    private final AzureResourceManager azure;

    public AksManager() {
        var credential = new DefaultAzureCredentialBuilder().build();
        var profile = new AzureProfile(AzureEnvironment.AZURE);
        this.azure = AzureResourceManager.authenticate(credential, profile)
            .withDefaultSubscription();
    }

    /**
     * Create an AKS cluster for the DevOps application
     */
    public KubernetesCluster createCluster(String clusterName, String resourceGroup, String dnsPrefix) {
        System.out.println("☸️  Creating AKS cluster: " + clusterName);

        // Create resource group if not exists
        if (azure.resourceGroups().getByName(resourceGroup) == null) {
            azure.resourceGroups().define(resourceGroup)
                .withRegion(Region.US_EAST)
                .withTag("Project", "devops-app")
                .create();
        }

        KubernetesCluster cluster = azure.kubernetesClusters().define(clusterName)
            .withRegion(Region.US_EAST)
            .withExistingResourceGroup(resourceGroup)
            .withDefaultVersionProfile()
            .withRootCaCertificate("")  // Auto-generated
            .withDnsPrefix(dnsPrefix)
            .withSystemAssignedManagedServiceIdentity()

            // Primary node pool (system workloads)
            .defineAgentPool("systempool")
                .withVirtualMachineSize(ContainerServiceVMSizeTypes.STANDARD_D4_V3)
                .withAgentPoolVirtualMachineCount(2)
                .withAgentPoolMode(AgentPoolMode.SYSTEM)
                .withOSType(OSType.LINUX)
                .withOSDiskSizeInGB(128)
                .withAutoScaling(2, 5)
                .attach()

            // User node pool (application workloads)
            .defineAgentPool("apppool")
                .withVirtualMachineSize(ContainerServiceVMSizeTypes.STANDARD_D8_V3)
                .withAgentPoolVirtualMachineCount(3)
                .withAgentPoolMode(AgentPoolMode.USER)
                .withOSType(OSType.LINUX)
                .withOSDiskSizeInGB(256)
                .withAutoScaling(3, 10)
                .withTaints(List.of("workload=app:NoSchedule"))
                .attach()

            // Network configuration (Azure CNI)
            .withNetworkProfile(
                new ContainerServiceNetworkProfile()
                    .withNetworkPlugin(NetworkPlugin.AZURE)
                    .withNetworkPolicy(NetworkPolicy.CALICO)
                    .withServiceCidr("10.0.0.0/16")
                    .withDnsServiceIP("10.0.0.10")
                    .withDockerBridgeCidr("172.17.0.1/16")
                    .withLoadBalancerSku(LoadBalancerSku.STANDARD)
                    .withOutboundType(OutboundType.LOAD_BALANCER)
            )

            // Enable monitoring and logging
            .withAddonProfiles(Map.of(
                "omsagent", new ManagedClusterAddonProfile()
                    .withEnabled(true)
                    .withConfig(Map.of(
                        "logAnalyticsWorkspaceResourceID", 
                        "/subscriptions/.../workspaces/myworkspace"
                    ))
            ))

            // Enable Azure Policy
            .withAzurePolicyAddon(new ManagedClusterAzureMonitorProfile()
                .withEnabled(true)
            )

            // RBAC enabled with Azure AD integration
            .withRoleBasedAccessControl(
                new ManagedClusterPropertiesForSnapshot()
                    .withEnableRBAC(true)
            )

            .withTags(Map.of(
                "Name", clusterName,
                "Project", "devops-app",
                "Environment", "production"
            ))
            .create();

        System.out.println("✅ AKS cluster created: " + cluster.fqdn());
        System.out.println("   API Server: " + cluster.fqdn());
        System.out.println("   Kubernetes Version: " + cluster.version());
        System.out.println("   Node Pools: systempool (2-5), apppool (3-10)");

        return cluster;
    }

    /**
     * Configure AKS for GitOps with Flux
     */
    public void enableGitOps(String clusterName, String resourceGroup, String gitRepo) {
        System.out.println("🔄 Enabling GitOps for " + clusterName);

        // In production, use Azure CLI or ARM templates
        // az k8s-configuration flux create \
        //   --cluster-name mycluster \
        //   --resource-group myrg \
        //   --name gitops-config \
        //   --namespace flux-system \
        //   --scope cluster \
        //   --url https://github.com/mycompany/gitops \
        //   --branch main \
        //   --kustomization name=apps path=./apps prune=true

        System.out.println("   Git Repository: " + gitRepo);
        System.out.println("   Sync Interval: 5 minutes");
        System.out.println("   Prune: enabled");
    }

    /**
     * Get kubeconfig for kubectl access
     */
    public void getKubeconfig(String clusterName, String resourceGroup) {
        KubernetesCluster cluster = azure.kubernetesClusters()
            .getByResourceGroup(resourceGroup, clusterName);

        String kubeconfig = cluster.adminKubeConfigContent();
        System.out.println("📄 Kubeconfig retrieved (save to ~/.kube/config)");
        System.out.println("   Context: " + clusterName);
    }

    /**
     * Scale node pool
     */
    public void scaleNodePool(String clusterName, String resourceGroup, 
                              String poolName, int nodeCount) {
        KubernetesCluster cluster = azure.kubernetesClusters()
            .getByResourceGroup(resourceGroup, clusterName);

        cluster.update()
            .updateAgentPool(poolName)
            .withVirtualMachineCount(nodeCount)
            .parent()
            .apply();

        System.out.println("📈 Scaled " + poolName + " to " + nodeCount + " nodes");
    }

    /**
     * Upgrade Kubernetes version
     */
    public void upgradeCluster(String clusterName, String resourceGroup, String targetVersion) {
        System.out.println("⬆️  Upgrading " + clusterName + " to Kubernetes " + targetVersion);

        KubernetesCluster cluster = azure.kubernetesClusters()
            .getByResourceGroup(resourceGroup, clusterName);

        cluster.update()
            .withVersion(targetVersion)
            .apply();

        System.out.println("✅ Upgrade initiated. Monitor with: az aks get-upgrades");
    }

    public static void main(String[] args) {
        var aks = new AksManager();

        // Create production cluster
        aks.createCluster("devops-aks-prod", "devops-app-production", "devops-prod");

        // Enable GitOps
        aks.enableGitOps("devops-aks-prod", "devops-app-production", 
            "https://github.com/mycompany/gitops");

        // Scale based on load
        aks.scaleNodePool("devops-aks-prod", "devops-app-production", "apppool", 5);

        // Upgrade when new version available
        aks.upgradeCluster("devops-aks-prod", "devops-app-production", "1.29.0");
    }
}

