// Java: Upload files to Azure Blob Storage
import com.azure.storage.blob.BlobClient;
import com.azure.storage.blob.BlobContainerClient;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;

@RestController
@RequestMapping("/api/files")
public class FileController {

    @Autowired
    private BlobContainerClient blobContainerClient;

    @PostMapping("/upload")
    public ResponseEntity<String> uploadFile(@RequestParam("file") MultipartFile file) {
        String blobName = UUID.randomUUID() + "-" + file.getOriginalFilename();
        BlobClient blobClient = blobContainerClient.getBlobClient(blobName);

        try {
            blobClient.upload(file.getInputStream(), file.getSize(), true);
            return ResponseEntity.ok(blobClient.getBlobUrl());
        } catch (IOException e) {
            return ResponseEntity.status(500).body("Upload failed: " + e.getMessage());
        }
    }

    @GetMapping("/{blobName}")
    public ResponseEntity<byte[]> downloadFile(@PathVariable String blobName) {
        BlobClient blobClient = blobContainerClient.getBlobClient(blobName);
        ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
        blobClient.download(outputStream);
        return ResponseEntity.ok(outputStream.toByteArray());
    }
}

